package system

const panelHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Codex Orchestrator</title>
<style nonce="PANEL_TOKEN">
:root{color-scheme:dark;font:15px system-ui,sans-serif;background:#0b101b;color:#e6edf7}*{box-sizing:border-box}body{margin:0}header{padding:24px 32px;border-bottom:1px solid #253048;display:flex;align-items:center;justify-content:space-between;gap:16px}h1{font-size:22px;margin:0}small,.muted{color:#98a8c2}main{max-width:1320px;padding:24px;margin:auto}.actions,nav{display:flex;gap:9px;flex-wrap:wrap}button,input,select,textarea{font:inherit;border:1px solid #33445f;border-radius:8px;background:#18243a;color:#e6edf7;padding:10px 13px}button{cursor:pointer}button:hover,button.active{border-color:#79abff;background:#243959}button:disabled{opacity:.45;cursor:default}.primary{background:#285cd5}nav{margin:22px 0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat,.card{border:1px solid #253048;background:#111a2b;border-radius:12px;padding:18px}.stat b{font-size:30px;display:block;margin-top:7px}.card{margin:12px 0}.row{display:flex;justify-content:space-between;gap:18px;align-items:center}.badge{border-radius:20px;padding:5px 10px;background:#26344b;font-size:12px}.waiting,.changes{background:#654716;color:#ffd994}.running,.publishing{background:#153c72;color:#aad1ff}.passed,.completed{background:#164f39;color:#abefcd}h2{font-size:18px;margin:0 0 10px}h3{font-size:16px;margin:0}.detail{white-space:pre-wrap;overflow-wrap:anywhere;color:#c2cee0;line-height:1.6;margin:12px 0}a{color:#99beff}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}label{display:grid;gap:7px}textarea{width:100%;min-height:90px}.notice{padding:14px;border:1px solid #465778;background:#18263e;border-radius:9px;margin:14px 0}#toast{position:sticky;top:8px;z-index:2;display:none}#search{width:100%;margin-bottom:12px}.event{border-bottom:1px solid #243149;padding:14px 0}.mono{font:12px ui-monospace,monospace;overflow-wrap:anywhere}footer{padding:22px 0;color:#7e90af;font-size:12px}@media(max-width:720px){header{padding:18px;align-items:flex-start;flex-direction:column}.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.row{align-items:flex-start;flex-direction:column}main{padding:16px}}
</style></head><body><header><div><h1>Codex Orchestrator</h1><small>Tasks, agents, and operations</small></div><div class="actions"><button id="check">Check board</button><button id="pause">Pause scheduling</button><span id="health" class="badge">Connecting</span></div></header><main><div id="toast" class="notice"></div><section class="stats" id="stats"></section><nav id="nav"></nav><section id="content"></section><footer>Local operator dashboard. Credentials and raw agent conversations are never shown. Active work finishes when scheduling is paused.</footer></main>
<script nonce="PANEL_TOKEN">
const token='PANEL_TOKEN';let state={jobs:{},events:[]},tab='Tasks',search='',configDirty=false,activity={},drafts={},selectedLog=null;const query=new URLSearchParams(location.search);if(query.get('tab')==='Agents')tab='Agents';if(query.get('task'))selectedLog={id:query.get('task'),role:query.get('role')||'executor'};
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function toast(text){const n=document.getElementById('toast');n.textContent=text;n.style.display='block';setTimeout(()=>n.style.display='none',12000)}
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{'X-Panel-Token':token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(await r.text());if(r.status===202){toast(await r.text());return {queued:true}}return r.json()}
async function command(action,id,text,patch){try{const r=await api('/api/command',{action:action,id:id||'',text:text||'',patch:patch||null});toast(r.queued?'Command queued':'Request accepted');await refresh()}catch(e){toast(e.message)}}
function button(text,fn,cls){const n=el('button',cls,text);n.onclick=fn;return n}
function date(v){return !v||v.startsWith('0001')?'Not recorded':new Date(v).toLocaleString()}
function elapsed(v){if(!v||v.startsWith('0001'))return 'Start time not recorded';return Math.max(0,Math.floor((Date.now()-Date.parse(v))/60000))+' min elapsed'}
function stage(j){const n=el('span','badge '+j.stage,j.stage);return n}
function jobs(){return Object.values(state.jobs||{}).filter(j=>j.id!=='manager')}
function render(){
 const all=jobs(),counts=[['Active agents',all.filter(j=>['running','publishing'].includes(j.stage)).length],['Waiting',all.filter(j=>j.stage==='waiting').length],['Queued',all.filter(j=>['queued','review','publish'].includes(j.stage)).length],['Review passed',all.filter(j=>j.stage==='passed').length]];
 const stats=document.getElementById('stats');stats.replaceChildren();counts.forEach(([name,count])=>{const n=el('div','stat',name);n.append(el('b','',count));stats.append(n)});
 document.getElementById('health').textContent=state.paused?'Scheduling paused':'Controller connected';document.getElementById('pause').textContent=state.paused?'Resume scheduling':'Pause scheduling';
 const nav=document.getElementById('nav');nav.replaceChildren();['Tasks','Agents','Configuration','Events'].forEach(name=>nav.append(button(name,()=>{tab=name;render();if(name==='Configuration')loadConfig()},tab===name?'active':'')));
 if(tab==='Configuration'){if(!document.getElementById('configForm'))loadConfig();return}
 const root=document.getElementById('content');root.replaceChildren();
 if(tab==='Tasks'){
  const input=el('input');input.id='search';input.placeholder='Search task title, ID, or status';input.value=search;input.oninput=()=>{search=input.value;renderTasks()};root.append(input,el('div'));root.lastChild.id='taskList';renderTasks();
 }else if(tab==='Agents'){
  const active=Object.values(state.jobs||{}).filter(j=>['running','publishing'].includes(j.stage));
  if(!active.length)root.append(el('div','notice','No agents are running. Waiting tasks and their blockers are shown in Tasks.'));
  active.forEach(j=>{const card=el('article','card');const live=activity[j.id]||{};card.append(el('h2','',j.role+' · '+j.title),stage(j),el('p','muted',elapsed(j.run_started_at)),el('p','muted',(live.event||'Awaiting session telemetry')+' · Last activity: '+date(live.last_activity)),el('p','mono','Task: '+j.id),el('p','mono','Session: '+(live.session||j.executor_session||j.reviewer_session||j.session||'Not recorded yet')),el('p','muted','Automatic refresh every 5 seconds. Timeline below shows starts, results, and blockers.'));card.append(button('View logs',()=>openAgentLogs(j.id,j.role==='publisher'?'executor':j.role)));root.append(card)});
    const history=el('details');history.append(el('summary','','Task agent logs (including completed tasks)'));
  Object.values(state.jobs||{}).forEach(j=>{const row=el('div','card');row.append(el('h3','',j.title));(j.id==='manager'?['manager']:['executor','reviewer']).forEach(role=>row.append(button(role+' logs',()=>openAgentLogs(j.id,role))));history.append(row)});root.append(history,el('div'));root.lastChild.id='agentLogs';
  if(selectedLog)loadAgentLogs();
  renderEvents(root,state.events.slice(-15));
 }else renderEvents(root,state.events);
}
function openAgentLogs(id,role){selectedLog={id:id,role:role};loadAgentLogs()}
async function loadAgentLogs(){try{const selected=selectedLog;if(!selected)return;const logs=await api('/api/agent-logs?id='+encodeURIComponent(selected.id)+'&role='+encodeURIComponent(selected.role));if(tab!=='Agents'||selected!==selectedLog)return;const root=document.getElementById('agentLogs');if(!root)return;root.replaceChildren();const card=el('article','card');card.append(el('h2','',selected.role+' logs · '+selected.id),el('p','muted',logs.notice),el('p','mono','Session: '+(logs.session||'not recorded')),button('Close logs',()=>{selectedLog=null;root.replaceChildren()}));(logs.entries||[]).forEach(entry=>{const block=el('div','event');block.append(el('small','',date(entry.at)+' · '+entry.kind),el('pre','detail mono',entry.text));card.append(block)});if(!logs.entries.length)card.append(el('p','muted','No displayable entries.'));root.append(card)}catch(e){toast(e.message)}}
function renderTasks(){const root=document.getElementById('taskList');if(!root)return;root.replaceChildren();const list=jobs().filter(j=>(j.title+' '+j.id+' '+j.stage).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>((a.stage==='closed')-(b.stage==='closed'))||a.title.localeCompare(b.title));
 list.forEach(j=>{const card=el('article','card'),row=el('div','row');row.append(el('h3','',j.title),stage(j));card.append(row,el('p','muted',j.role+' · '+j.id));
  if(j.question)card.append(el('div','notice',j.question));else if(j.last_error)card.append(el('div','notice',j.last_error));
  if(j.retry_at&&!j.retry_at.startsWith('0001'))card.append(el('p','muted','Next retry: '+date(j.retry_at)));
  const details=el('details');details.append(el('summary','','Review and result details'),el('div','detail',(j.summary||'No result yet')+'\n\n'+(j.findings||[]).join('\n\n')),el('p','mono','Commit: '+(j.head||'not published')));card.append(details);
  const actions=el('div','actions');if(j.pr_url&&j.pr_url.startsWith('https://github.com/')){const a=el('a','','Open PR');a.href=j.pr_url;a.target='_blank';a.rel='noopener noreferrer';actions.append(a)}
  if(['waiting','queued','review'].includes(j.stage)&&!j.closed_pr){actions.append(button('Retry',()=>command('retry',j.id)));if(j.stage==='waiting'){const answer=el('textarea');answer.id='answer-'+j.id;answer.value=drafts[j.id]||'';answer.oninput=()=>drafts[j.id]=answer.value;answer.placeholder='Answer the agent or confirm the missing resource is ready';card.append(answer);actions.append(button('Send answer',()=>command('answer',j.id,answer.value),'primary'))}}
  card.append(actions);root.append(card)
 });if(!list.length)root.append(el('div','notice','No matching tasks'))}
function renderEvents(root,events){root.append(el('h2','','Activity'));[...events].reverse().forEach(e=>{const n=el('div','event');n.append(el('small','',date(e.at)+' · '+e.kind+(e.task?' · '+e.task:'')),el('div','detail',e.message));root.append(n)});if(!events.length)root.append(el('p','muted','Events will appear as work progresses.'))}
async function loadConfig(){try{const cfg=await api('/api/config');if(tab!=='Configuration')return;const root=document.getElementById('content');root.replaceChildren();const form=el('form');form.id='configForm';const grid=el('div','grid');Object.entries(cfg).forEach(([key,value])=>{const label=el('label','',key.replaceAll('_',' '));let field;if(typeof value==='boolean'){field=el('select');['true','false'].forEach(v=>{const option=el('option','',v);option.value=v;field.append(option)})}else{field=el('input');field.type=typeof value==='number'?'number':'text'}field.name=key;field.value=String(value);field.dataset.kind=typeof value;label.append(field);grid.append(label)});form.append(el('h2','','Runtime configuration'),el('p','muted','Changes are validated, saved, and applied when all workers are idle. Credentials, isolation, and repository access remain managed by the setup files.'),grid,button('Save configuration',()=>{},'primary'));form.onsubmit=e=>{e.preventDefault();const patch={};form.querySelectorAll('input,select').forEach(f=>patch[f.name]=f.dataset.kind==='number'?Number(f.value):f.dataset.kind==='boolean'?f.value==='true':f.value);command('config','', '',patch)};root.append(form);if(state.pending_config)root.prepend(el('div','notice','Configuration change is pending until active workers finish.'))}catch(e){toast(e.message)}}
async function refresh(){const focused=document.activeElement;const focusID=focused.id;const position=focused.selectionStart;try{state=await api('/api/status');if(tab==='Agents')activity=await api('/api/activity');render();const restored=document.getElementById(focusID);if(restored){restored.focus();if(position!==null&&position!==undefined&&restored.setSelectionRange)restored.setSelectionRange(position,position)}}catch(e){document.getElementById('health').textContent='Connection lost';toast('Controller unavailable: '+e.message)}}
document.getElementById('check').onclick=()=>command('check');document.getElementById('pause').onclick=()=>command(state.paused?'resume':'pause');refresh();setInterval(refresh,5000);
</script></body></html>`
